import com.github.benmanes.caffeine.cache.*;
import java.time.Duration;
import java.util.function.Function;
public final class ProductLookup {
  private final Function<String,String> origin;
  private final LoadingCache<String,String> cache;
  public ProductLookup(Function<String,String> origin) {
    this.origin=origin;
    this.cache=Caffeine.newBuilder().maximumSize(100).expireAfterWrite(Duration.ofMinutes(10)).build(origin::apply);
  }
  public String find(String key) {
    String value=cache.getIfPresent(key);
    if(value==null) { value=origin.apply(key); cache.put(key,value); }
    return value;
  }
}

